-- Dois módulos novos:
--   * Inventários (base histórica): inventários do sistema legado por unidade, com resultado por categoria.
--   * Mapa de Risco: matriz de risco por unidade, agenda de visitas, produtividade, planejamento,
--     histórico de notas de auditoria e Programa Filial Destaque (pontuação, selos e certificados).
-- Esta migração só ACRESCENTA estruturas e dados. Nada existente é alterado ou apagado.
-- As unidades são ligadas ao cadastro único de filiais pelo número (ex.: "NEVOEIRO 01" -> filial 1);
-- o app faz essa ligação, e o nome original fica guardado em "empresa"/"nome".

-- =====================================================================
-- 1. Inventários (base histórica)
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.inv_inventarios (
  id text PRIMARY KEY,
  cau_id integer NOT NULL,                 -- número do inventário no sistema legado (liga às categorias)
  descricao text NOT NULL DEFAULT '',
  tin_id integer,
  cfi_id integer,
  empresa text NOT NULL DEFAULT '',        -- unidade como veio do sistema legado (ex.: NEVOEIRO 01)
  filial_id text REFERENCES public.filiais (id),
  agendamento text NOT NULL DEFAULT '',    -- período do inventário (ex.: 11/04/2023 ~ 18/04/2023)
  data date,                               -- início do período (ordenação e filtros)
  sistema numeric NOT NULL DEFAULT 0,
  contagem numeric NOT NULL DEFAULT 0,
  faltas numeric NOT NULL DEFAULT 0,
  sobras numeric NOT NULL DEFAULT 0,
  resultado numeric NOT NULL DEFAULT 0,
  faltas_rs numeric NOT NULL DEFAULT 0,    -- valores em R$ (custo)
  sobras_rs numeric NOT NULL DEFAULT 0,
  resultado_rs numeric NOT NULL DEFAULT 0,
  acuracia numeric,
  eficiencia numeric,
  ativo boolean NOT NULL DEFAULT true,     -- inativo = fica fora das somas
  origem text NOT NULL DEFAULT 'manual' CHECK (origem IN ('historico', 'manual')),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS inv_inventarios_updated_idx ON public.inv_inventarios (updated_at, id);
CREATE INDEX IF NOT EXISTS inv_inventarios_cau_idx ON public.inv_inventarios (cau_id);

CREATE TABLE IF NOT EXISTS public.inv_categorias (
  id text PRIMARY KEY,
  cau_id integer NOT NULL,
  empresa text NOT NULL DEFAULT '',
  classe text NOT NULL DEFAULT '',
  sistema numeric NOT NULL DEFAULT 0,
  contagem numeric NOT NULL DEFAULT 0,
  faltas numeric NOT NULL DEFAULT 0,
  sobras numeric NOT NULL DEFAULT 0,
  resultado numeric NOT NULL DEFAULT 0,
  faltas_rs numeric NOT NULL DEFAULT 0,
  sobras_rs numeric NOT NULL DEFAULT 0,
  resultado_rs numeric NOT NULL DEFAULT 0,
  faltas_venda_rs numeric,                 -- valores de venda (só nas categorias lançadas no app)
  sobras_venda_rs numeric,
  resultado_venda_rs numeric,
  acuracia numeric,
  eficiencia numeric,
  ativo boolean NOT NULL DEFAULT true,
  origem text NOT NULL DEFAULT 'manual' CHECK (origem IN ('historico', 'manual')),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS inv_categorias_cau_idx ON public.inv_categorias (cau_id);
CREATE INDEX IF NOT EXISTS inv_categorias_updated_idx ON public.inv_categorias (updated_at, id);

-- =====================================================================
-- 2. Mapa de Risco e Programa Filial Destaque
-- =====================================================================
-- Unidade avaliada (uma filial pode ter mais de uma, ex.: "2 Loja" e "2 Pista").
CREATE TABLE IF NOT EXISTS public.rm_unidades (
  id text PRIMARY KEY,
  nome text NOT NULL,
  filial_id text REFERENCES public.filiais (id),
  p smallint NOT NULL DEFAULT 0 CHECK (p BETWEEN 0 AND 5),    -- Produtos
  c smallint NOT NULL DEFAULT 0 CHECK (c BETWEEN 0 AND 5),    -- Combustíveis
  cx smallint NOT NULL DEFAULT 0 CHECK (cx BETWEEN 0 AND 5),  -- Caixa / Valores
  pe smallint NOT NULL DEFAULT 0 CHECK (pe BETWEEN 0 AND 5),  -- Pessoas e Gestão
  h smallint NOT NULL DEFAULT 0 CHECK (h BETWEEN 0 AND 5),    -- Histórico Auditorias
  ultima_revisao date,
  proxima_visita date,
  notas jsonb NOT NULL DEFAULT '{}'::jsonb,                   -- notas mensais de auditoria: {"2026-01": 6}
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS rm_unidades_updated_idx ON public.rm_unidades (updated_at, id);

-- Pontuação lançada no Programa Filial Destaque (uma por unidade e mês).
CREATE TABLE IF NOT EXISTS public.rm_pontuacoes (
  id text PRIMARY KEY,                      -- '<unidade_id>:<AAAA-MM>'
  unidade_id text NOT NULL,
  periodo text NOT NULL CHECK (periodo ~ '^\d{4}-\d{2}$'),
  nota numeric NOT NULL CHECK (nota BETWEEN 0 AND 10),
  p smallint NOT NULL CHECK (p BETWEEN 1 AND 5),
  c smallint NOT NULL CHECK (c BETWEEN 1 AND 5),
  cx smallint NOT NULL CHECK (cx BETWEEN 1 AND 5),
  pe smallint NOT NULL CHECK (pe BETWEEN 1 AND 5),
  h smallint NOT NULL CHECK (h BETWEEN 1 AND 5),
  planos numeric NOT NULL DEFAULT 100 CHECK (planos BETWEEN 0 AND 100),
  obs text NOT NULL DEFAULT '',
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS rm_pontuacoes_updated_idx ON public.rm_pontuacoes (updated_at, id);

-- Produtividade: atividades registradas na visita; pendentes viram plano de ação para a próxima visita.
CREATE TABLE IF NOT EXISTS public.rm_atividades (
  id text PRIMARY KEY,
  unidade_id text NOT NULL,
  data date NOT NULL,
  tarefa text NOT NULL,
  categoria text NOT NULL DEFAULT 'Checklist',
  obs text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'Concluído' CHECK (status IN ('Pendente', 'Concluído')),
  levar_proxima boolean NOT NULL DEFAULT false,
  proxima_visita date,
  evidencia jsonb,                          -- {"path","nome","tipo"} no bucket riscos-evidencias
  concluido_em timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS rm_atividades_updated_idx ON public.rm_atividades (updated_at, id);

-- Planejamento: uma visita = unidade + data, com as demandas em JSONB.
CREATE TABLE IF NOT EXISTS public.rm_visitas (
  id text PRIMARY KEY,                      -- '<unidade_id>:<AAAA-MM-DD>'
  unidade_id text NOT NULL,
  data date NOT NULL,
  tarefas jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS rm_visitas_updated_idx ON public.rm_visitas (updated_at, id);

-- =====================================================================
-- 3. updated_at pelo servidor e acesso por módulo (exclusão lógica, por UPDATE)
-- =====================================================================
DO $$
DECLARE t text; m text;
BEGIN
  FOREACH t IN ARRAY ARRAY['inv_inventarios', 'inv_categorias', 'rm_unidades', 'rm_pontuacoes', 'rm_atividades', 'rm_visitas'] LOOP
    m := CASE WHEN t LIKE 'inv_%' THEN 'inventarios' ELSE 'riscos' END;
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_touch', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION private.touch_updated_at()', t || '_touch', t);
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS "Modulo le" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "Modulo insere" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "Modulo altera" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Modulo le" ON public.%I FOR SELECT TO authenticated USING ((SELECT private.tem_modulo(%L)))', t, m);
    EXECUTE format('CREATE POLICY "Modulo insere" ON public.%I FOR INSERT TO authenticated WITH CHECK ((SELECT private.tem_modulo(%L)))', t, m);
    EXECUTE format('CREATE POLICY "Modulo altera" ON public.%I FOR UPDATE TO authenticated USING ((SELECT private.tem_modulo(%L))) WITH CHECK ((SELECT private.tem_modulo(%L)))', t, m, m);
  END LOOP;
END $$;

-- ---------- Evidências do Mapa de Risco (Storage, bucket privado) ----------
DO $$
BEGIN
  VALUES ('riscos-evidencias', 'riscos-evidencias', false, 10485760, ARRAY[
    'image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
  ON CONFLICT (id) DO NOTHING;
EXCEPTION WHEN insufficient_privilege THEN
  RAISE WARNING 'Sem permissão para criar o bucket riscos-evidencias: crie no painel do Supabase (Storage), privado, limite 10 MB.';
END $$;

DO $$
BEGIN
  DROP POLICY IF EXISTS "Riscos evidencias le" ON storage.objects;
  DROP POLICY IF EXISTS "Riscos evidencias envia" ON storage.objects;
  DROP POLICY IF EXISTS "Riscos evidencias apaga" ON storage.objects;
  CREATE POLICY "Riscos evidencias le" ON storage.objects FOR SELECT TO authenticated
    USING (bucket_id = 'riscos-evidencias' AND (SELECT private.tem_modulo('riscos')));
  CREATE POLICY "Riscos evidencias envia" ON storage.objects FOR INSERT TO authenticated
    WITH CHECK (bucket_id = 'riscos-evidencias' AND (SELECT private.tem_modulo('riscos')));
  CREATE POLICY "Riscos evidencias apaga" ON storage.objects FOR DELETE TO authenticated
    USING (bucket_id = 'riscos-evidencias' AND (SELECT private.tem_modulo('riscos')));
EXCEPTION WHEN insufficient_privilege THEN
  RAISE WARNING 'Sem permissão para criar as políticas do Storage: crie no painel (bucket riscos-evidencias) para SELECT, INSERT e DELETE de authenticated com a condição private.tem_modulo(''riscos'').';
END $$;

